language sql
immutable
set search_path = public
as $fn$
  select ($conteudo${"caatedrum":{"historia":{"nome":"Caatedrum","abertura":["Caatedrum é uma fortaleza-catedral do tamanho de uma cidade. Uma escola, dizem. Uma prisão, sabem os que estudam nela: aqui se aprende a servir ao rei — na guerra, nas sombras, na chancelaria, na moeda — e quem não é escolhido nunca mais sai.","Marrow entrou aos doze anos para achar a irmã, Ysolde, que sumira antes dele. Trinta anos e três reprovações depois, roubou o Registro do Primeiro Mestre para ver o nome dela. O Registro o leu de volta.","Na mesma noite, no baile, o Mestre Orlan caiu morto à meia-noite. O assassino usava a Máscara de Raposa — a única que nenhum espelho reflete.","Duas duplas. Dois rastros. Um segue o nome; o outro segue o rosto. No fim, os dois se encontram na Banca."],"consentimento":["Este jogo pode quebrar a quarta parede: dicas falsas, coisas que somem da tela, nomes trocados por alguns segundos. É tudo parte de Caatedrum e fica dentro do site.","Qualquer pessoa pode apertar Pausar a qualquer momento — o jogo para para todos, sem perguntas."],"memoria_padrao":"Lembro do cheiro de tinta velha no primeiro dia, e de alguém dizendo meu nome na porta do refeitório como se já soubesse que eu ia ficar.","duplas":{"A":{"nome":"O Registro Perdido","lugar":"Ala do Arquivo","segue":"o nome","abertura":"O Registro do Primeiro Mestre sumiu da Ala Proibida ao terceiro sino. Vocês seguem o nome."},"B":{"nome":"O Assassino Mascarado","lugar":"Salão dos Rostos","segue":"o rosto","abertura":"O Mestre Orlan, da Moeda, está morto no salão de baile. Vocês seguem o rosto."}},"fases":{"A":[{"n":1,"tipo":"Investigação","titulo":"Testemunhas de Papel","papeis":["interrogador","cruzador"]},{"n":2,"tipo":"Puzzle","titulo":"A Estante que Reordena","papeis":["linhas","colunas"]},{"n":3,"tipo":"Combate","titulo":"O Leitor","papeis":["gramatica","sentido"]}],"B":[{"n":1,"tipo":"Investigação","titulo":"O Baile em 3 Valsas","papeis":["mascaras","nomes"]},{"n":2,"tipo":"Puzzle","titulo":"O Corredor dos Espelhos","papeis":["maos","olhos"]},{"n":3,"tipo":"Combate","titulo":"O Colecionador","papeis":["ve","monta"]}]},"papeis":{"interrogador":{"nome":"Interrogador","resumo":"Você gasta tintas para ler os depoimentos. Só você vê os textos — e nunca a tinta deles."},"cruzador":{"nome":"Cruzador","resumo":"Você nunca lê os textos. Vê de que tinta é cada depoimento (fresca ou antiga) e monta a grade de deduções."},"linhas":{"nome":"Linhas","resumo":"Você vê só o capítulo de cada livro e só gira linhas."},"colunas":{"nome":"Colunas","resumo":"Você vê só a folha de cada livro e só gira colunas."},"gramatica":{"nome":"Gramática","resumo":"Você vê a frase com lacunas e as pistas de gramática."},"sentido":{"nome":"Sentido","resumo":"Você vê o banco de palavras e as pistas de significado."},"mascaras":{"nome":"Máscaras","resumo":"Você vê que máscara está em cada assento e as regras que movem as máscaras."},"nomes":{"nome":"Nomes","resumo":"Você vê quem está em cada assento, os motivos de cada convidado e as regras que movem as pessoas."},"maos":{"nome":"Mãos","resumo":"Você vê os pedestais e troca as máscaras de lugar. Não vê o reflexo."},"olhos":{"nome":"Olhos","resumo":"Você vê só o reflexo — o de agora e o do alvo."},"ve":{"nome":"Vê","resumo":"Você enxerga o rosto original e descreve em voz alta."},"monta":{"nome":"Monta","resumo":"Você reconstrói o rosto só pela descrição."}}},"a1":{"titulo":"Testemunhas de Papel","cenario":"O Registro sumiu da Ala Proibida ao terceiro sino. Cinco estudantes estavam no corredor, cada um numa ala diferente. Quem estava na Ala Proibida é o ladrão.","regras":["Cada livro tem exatamente um depoimento falso.","A mentira sempre tem tinta fresca — e em cada livro há também uma verdade de tinta fresca, como isca.","Tinta antiga é sempre verdade."],"alas":["Ala dos Mapas","Ala dos Selos","Ala dos Salmos","Ala das Genealogias","Ala Proibida"],"alas_curtas":["Mapas","Selos","Salmos","Genealogias","Proibida"],"suspeitos":["Ilvane","Brokk","Sessaly","Marrow","Quenn"],"tintas":12,"livros":[{"id":"horas","titulo":"Livro de Horas"},{"id":"contas","titulo":"Livro de Contas"},{"id":"visitas","titulo":"Livro de Visitas"},{"id":"sombras","titulo":"Livro das Sombras"},{"id":"ecos","titulo":"Livro de Ecos"}],"depoimentos":[{"livro":"horas","n":1,"tipo":"left","args":["Sessaly","Quenn"],"tinta":"fresca","verdade":false,"id":"horas-1","texto":"Sessaly estava mais perto da entrada do que Quenn."},{"livro":"horas","n":2,"tipo":"adj","args":["Marrow","Sessaly"],"tinta":"fresca","verdade":true,"id":"horas-2","texto":"Marrow estava numa ala vizinha à de Sessaly."},{"livro":"horas","n":3,"tipo":"not","args":["Brokk","Mapas"],"tinta":"antiga","verdade":true,"id":"horas-3","texto":"Brokk não estava na Ala dos Mapas."},{"livro":"contas","n":1,"tipo":"not","args":["Sessaly","Mapas"],"tinta":"antiga","verdade":true,"id":"contas-1","texto":"Sessaly não estava na Ala dos Mapas."},{"livro":"contas","n":2,"tipo":"left","args":["Quenn","Brokk"],"tinta":"fresca","verdade":true,"id":"contas-2","texto":"Quenn estava mais perto da entrada do que Brokk."},{"livro":"contas","n":3,"tipo":"left","args":["Sessaly","Brokk"],"tinta":"fresca","verdade":false,"id":"contas-3","texto":"Sessaly estava mais perto da entrada do que Brokk."},{"livro":"visitas","n":1,"tipo":"left","args":["Marrow","Ilvane"],"tinta":"fresca","verdade":false,"id":"visitas-1","texto":"Marrow estava mais perto da entrada do que Ilvane."},{"livro":"visitas","n":2,"tipo":"is","args":["Quenn","Mapas"],"tinta":"antiga","verdade":true,"id":"visitas-2","texto":"Quenn estava na Ala dos Mapas."},{"livro":"visitas","n":3,"tipo":"is","args":["Ilvane","Selos"],"tinta":"fresca","verdade":true,"id":"visitas-3","texto":"Ilvane estava na Ala dos Selos."},{"livro":"sombras","n":1,"tipo":"left","args":["Quenn","Marrow"],"tinta":"fresca","verdade":true,"id":"sombras-1","texto":"Quenn estava mais perto da entrada do que Marrow."},{"livro":"sombras","n":2,"tipo":"not","args":["Marrow","Mapas"],"tinta":"antiga","verdade":true,"id":"sombras-2","texto":"Marrow não estava na Ala dos Mapas."},{"livro":"sombras","n":3,"tipo":"not","args":["Marrow","Proibida"],"tinta":"fresca","verdade":false,"id":"sombras-3","texto":"Marrow não estava na Ala Proibida."},{"livro":"ecos","n":1,"tipo":"left","args":["Ilvane","Sessaly"],"tinta":"antiga","verdade":true,"id":"ecos-1","texto":"Ilvane estava mais perto da entrada do que Sessaly."},{"livro":"ecos","n":2,"tipo":"left","args":["Brokk","Ilvane"],"tinta":"fresca","verdade":false,"id":"ecos-2","texto":"Brokk estava mais perto da entrada do que Ilvane."},{"livro":"ecos","n":3,"tipo":"is","args":["Brokk","Salmos"],"tinta":"fresca","verdade":true,"id":"ecos-3","texto":"Brokk estava na Ala dos Salmos."}],"solucao":{"Quenn":"Mapas","Ilvane":"Selos","Brokk":"Salmos","Sessaly":"Genealogias","Marrow":"Proibida"},"culpado":"Marrow","dicas":["Tinta antiga é sempre verdade — comecem por ela.","Um depoimento de tinta antiga já põe alguém na primeira ala.","O ladrão está entre Sessaly e Marrow."],"acusacao_errada":"A acusação ecoa vazia pelo arquivo. Duas tintas secam no tinteiro — e um dos livros se fecha com lacre de cera.","entrega":{"texto":"Marrow. O nome cai do livro como uma folha solta. Na margem, alguém desenhou um livro no canto de uma estante: \"O Livro Que Me Leu\".","nome":"Marrow","fragmento":"MAR","libera":"Na Estante que Reordena, a célula do canto inferior direito — \"O Livro Que Me Leu\" — já começa certa e marcada."},"lacre_ordem":["horas","contas"]},"b1":{"titulo":"O Baile em 3 Valsas","cenario":"O Mestre Orlan foi achado morto à meia-noite. O assassino usava a Máscara de Raposa. Oito assentos em círculo, numerados de 0 a 7 no sentido horário a partir da porta. A cada valsa, máscaras e pessoas trocam de lugar — cada uma por uma regra diferente.","assentos":8,"mascaras":["Lua","Sol","Estrela","Corvo","Névoa","Raposa","Serpente","Cervo"],"pessoas":["Aldric","Bessa","Corvin","Fenna","Dessa","Ewan","Gorm","Hilde"],"operacoes":{"girar":"Girar k no sentido horário: quem estava no assento i vai para o assento i + k (dando a volta no círculo). k negativo gira no sentido anti-horário.","pares":"Trocar pares: trocam de lugar os assentos 0 e 1, 2 e 3, 4 e 5, 6 e 7.","oposto":"Oposto: cada um vai para o assento da frente (i + 4, dando a volta).","espelhar":"Espelhar: quem está no assento i vai para o assento 7 − i.","inverter03":"Inverter 0 a 3: trocam de lugar os assentos 0 e 3, e 1 e 2. Os outros ficam."},"valsas":[{"n":1,"mascaras":{"op":"girar","k":3,"texto":"As máscaras giram 3 assentos no sentido horário."},"pessoas":{"op":"girar","k":-2,"texto":"As pessoas giram 2 assentos no sentido anti-horário."}},{"n":2,"mascaras":{"op":"pares","texto":"As máscaras trocam de lugar aos pares."},"pessoas":{"op":"oposto","texto":"As pessoas vão para o assento oposto."}},{"n":3,"mascaras":{"op":"espelhar","texto":"As máscaras se espelham."},"pessoas":{"op":"inverter03","texto":"As pessoas dos assentos 0 a 3 se invertem."}}],"esperado":{"mascaras":["Corvo","Névoa","Sol","Estrela","Cervo","Lua","Raposa","Serpente"],"pessoas":["Bessa","Aldric","Hilde","Gorm","Corvin","Fenna","Dessa","Ewan"]},"motivos":[{"nome":"Dessa","texto":"Foi reprovada três vezes sob o Mestre Orlan."},{"nome":"Gorm","texto":"Devia dinheiro a Orlan."},{"nome":"Corvin","texto":"Era rival acadêmico dele."},{"nome":"Hilde","texto":"Era a aprendiz favorita de Orlan. Nenhum motivo conhecido."},{"nome":"Aldric","texto":"Estava com o mestre de cerimônias a noite toda. Tem álibi."},{"nome":"Bessa","texto":"Tocava na orquestra durante as três valsas. Tem álibi."},{"nome":"Fenna","texto":"Foi vista na cozinha à meia-noite. Tem álibi."},{"nome":"Ewan","texto":"Passou o baile ao lado da Reitora. Tem álibi."}],"culpado":"Dessa","relogio_min":8,"acusacao_errada_seg":60,"dicas":["Façam as três valsas uma de cada vez, em voz alta: Máscaras diz onde está a Raposa depois de cada valsa.","Depois da primeira valsa, a Raposa está no assento 0.","A Raposa termina no assento 6. Nomes: quem está no assento 6 no fim?"],"acusacao_errada":"A orquestra para no meio do compasso. Os convidados olham para vocês — e o relógio da torre adianta um minuto.","entrega":{"texto":"Dessa. Por trás da Raposa, três traços: uma cicatriz em forma de chave no queixo, olhos de cores diferentes, uma mecha branca no cabelo. A Raposa não reflete em espelho nenhum — e ela fugiu pelo Corredor dos Espelhos.","nome":"Dessa","tracos":["cicatriz em forma de chave no queixo","olhos de cores diferentes","mecha branca no cabelo"],"libera":"No Corredor dos Espelhos, Mãos sabe qual das máscaras é a Raposa — a que nenhum espelho reflete."},"assento_final":6}}}$conteudo$::jsonb) -> p_game;
$fn$;

revoke all on function public.enigma_content(text) from public, anon, authenticated;
